:where(.np-typeset, [data-np-typeset]) {
  --np-typeset-font-heading: inherit;
  --np-typeset-font-body: inherit;
  --np-typeset-font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    monospace;
  --np-typeset-size: 1em;
  --np-typeset-bump: 1;
  --np-typeset-leading: 1.75;
  --np-typeset-flow: 1.25em;
  --np-typeset-color: var(--np-foreground);
  --np-typeset-muted: var(--np-muted-foreground);
  --np-typeset-rule: var(--np-border);
  --np-typeset-radius: var(--np-radius-lg);

  font-family: var(--np-typeset-font-body, inherit);
  font-size: calc(var(--np-typeset-size) * var(--np-typeset-bump));
  line-height: var(--np-typeset-leading);
  color: var(--np-typeset-color);
  overflow-wrap: break-word;
  margin-trim: block-start;
}

@media (max-width: 47.9375rem) {
  :where(.np-typeset, [data-np-typeset]) {
    --np-typeset-bump: 1.125;
  }
}

@media print {
  :where(.np-typeset, [data-np-typeset]) {
    --np-typeset-bump: 1;
  }
}

:where(.np-typeset, [data-np-typeset])
  :where(p):not(
    :where(
      .np-typeset-not,
      [data-np-typeset-not],
      .np-typeset-not *,
      [data-np-typeset-not] *
    )
  ) {
  margin-block-start: var(--np-typeset-flow);
  margin-block-end: 0;
  text-wrap: pretty;
}

:where(.np-typeset, [data-np-typeset])
  :where(h1, h2, h3, h4, h5, h6):not(
    :where(
      .np-typeset-not,
      [data-np-typeset-not],
      .np-typeset-not *,
      [data-np-typeset-not] *
    )
  ) {
  color: var(--np-typeset-color);
  font-family: var(
    --np-typeset-font-heading,
    var(--np-typeset-font-body, inherit)
  );
  font-weight: 600;
  margin-block-end: 0;
  text-wrap: balance;
}

